package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.*;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import com.fasterxml.jackson.databind.*;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
/** Actual PG fencing only. No application Worker, upload, download, notification or membership mutation. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresAssetExportClaimIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",ROUTE="POST /integration/export-claim-accept";
    static HikariDataSource pool;static PostgresPlatformRepository platform;static PostgresAssetExportRepository exports;static ObjectMapper mapper;static String admin;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(5);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().findAndRegisterModules().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);exports=new PostgresAssetExportRepository(pool,platform);admin=platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals("padmin")).isPresent()).findFirst().orElseThrow().id();}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static AssetExportJobRepository.Access access(){return new AssetExportJobRepository.Access(admin,TENANT,platform.membership(admin,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Job accept(String key){var a=access();var f=new Filters(null,null,"","SYNTHETIC_CLAIM");return mapper.convertValue(platform.idempotentAuthorized(a.actorId(),a.tenantId(),ROUTE,key,"a".repeat(64),a.permissionVersion(),()->exports.authorizeAcceptance(a),()->exports.accept(a,f)),Job.class);}
    static Job accept(){return accept(UUID.randomUUID().toString());}
    static long count(String table)throws Exception{assertTrue(Set.of("mop_asset_export_job","mop_asset_export_attempt","mop_audit").contains(table));try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public."+table)){r.next();return r.getLong(1);}}
    static long attempts(String id)throws Exception{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM public.mop_asset_export_attempt WHERE job_id=?::uuid")){s.setString(1,id);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    static void pause()throws Exception{try(var c=pool.getConnection();var s=c.createStatement()){s.execute("SELECT pg_sleep(0.06)");}}
    @Test void claimPersistsFenceAttemptAndAuditButOriginalReceiptRemainsQueued()throws Exception{String key=UUID.randomUUID().toString();var original=accept(key);long audit=count("mop_audit");var claim=exports.claim(original.id(),"real-claim-one",Duration.ofSeconds(30)).orElseThrow();assertEquals(original.id(),claim.jobId());assertEquals(1,claim.fencingToken());assertEquals(1,claim.version());assertFalse(claim.storageReconciliationRequired());assertEquals(original.filters(),claim.command().filters());assertEquals(original.inputSha256(),claim.command().fingerprint());assertEquals(State.RUNNING,exports.get(access(),original.id()).state());assertEquals(1,attempts(original.id()));assertEquals(audit+1,count("mop_audit"));assertEquals(original,accept(key));}
    @Test void activeLeaseCannotBeStolenAndNoExtraAttemptIsWritten()throws Exception{var job=accept();var first=exports.claim(job.id(),"first",Duration.ofSeconds(30)).orElseThrow();long audit=count("mop_audit");assertTrue(exports.claim(job.id(),"second",Duration.ofSeconds(30)).isEmpty());assertEquals(1,attempts(job.id()));assertEquals(first.version(),exports.get(access(),job.id()).version());assertEquals(audit,count("mop_audit"));}
    @Test void expiredUnpreparedClaimReclaimsWithIncreasingFenceAndSameCommand()throws Exception{var job=accept();var first=exports.claim(job.id(),"first",Duration.ofMillis(20)).orElseThrow();pause();var second=exports.claim(job.id(),"second",Duration.ofSeconds(30)).orElseThrow();assertEquals(2,second.fencingToken());assertEquals(first.command(),second.command());assertFalse(second.storageReconciliationRequired());assertEquals(2,attempts(job.id()));}
    @Test void twoConnectionsContendingForOneJobOnlyOneOwnsItsLease()throws Exception{var job=accept();var ready=new CountDownLatch(2);var go=new CountDownLatch(1);var executor=Executors.newFixedThreadPool(2);long audit=count("mop_audit");try{Callable<Optional<Claim>> action=()->{ready.countDown();assertTrue(go.await(5,TimeUnit.SECONDS));return exports.claim(job.id(),"race-"+Thread.currentThread().getId(),Duration.ofSeconds(30));};var a=executor.submit(action);var b=executor.submit(action);assertTrue(ready.await(5,TimeUnit.SECONDS));go.countDown();assertEquals(1,(a.get(10,TimeUnit.SECONDS).isPresent()?1:0)+(b.get(10,TimeUnit.SECONDS).isPresent()?1:0));}finally{executor.shutdownNow();}assertEquals(1,attempts(job.id()));assertEquals(audit+1,count("mop_audit"));}
    @Test void unknownJobReturnsEmptyWithoutAcceptanceAttemptOrAudit()throws Exception{long jobs=count("mop_asset_export_job"),audit=count("mop_audit"),attempts=count("mop_asset_export_attempt");assertTrue(exports.claim(UUID.randomUUID().toString(),"no-job",Duration.ofSeconds(1)).isEmpty());assertEquals(jobs,count("mop_asset_export_job"));assertEquals(audit,count("mop_audit"));assertEquals(attempts,count("mop_asset_export_attempt"));}
    @Test void invalidWorkerAndDurationRejectEvenWhenQueueTargetDoesNotExist()throws Exception{long audit=count("mop_audit");for(String worker:Arrays.asList(null,"","has space","x".repeat(65)))assertEquals(400,assertThrows(DomainException.class,()->exports.claim(UUID.randomUUID().toString(),worker,Duration.ofSeconds(1))).status);for(Duration lease:Arrays.asList(null,Duration.ZERO,Duration.ofMillis(-1),Duration.ofNanos(1),Duration.ofMinutes(11)))assertEquals(400,assertThrows(DomainException.class,()->exports.claim(UUID.randomUUID().toString(),"worker",lease)).status);assertEquals(audit,count("mop_audit"));}
    @Test void nestedWriteAndOtherOwnedRecordScopesAreNotInherited()throws Exception{var job=accept();var a=access();long audit=count("mop_audit");assertThrows(IllegalStateException.class,()->platform.idempotentAuthorized(admin,TENANT,ROUTE,UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->exports.authorizeAcceptance(a),()->exports.claim(job.id(),"nested",Duration.ofSeconds(30))));assertThrows(IllegalStateException.class,()->platform.exportJobTransaction(()->platform.idempotentCommandConnection()));assertThrows(IllegalStateException.class,()->platform.exportJobTransaction(()->platform.importCommandConnection()));assertThrows(IllegalStateException.class,()->platform.exportCommandConnection());assertEquals(0,attempts(job.id()));assertEquals(audit,count("mop_audit"));}
    @Test void staleCapturedPermissionIsFailedWithoutChangingActualMembershipOrClaiming()throws Exception{var a=access();String id=UUID.randomUUID().toString();var command=new Command(new AssetExportJobState.Access(UUID.fromString(TENANT),UUID.fromString(admin),a.permissionVersion()+1,"padmin",true),new Filters(null,null,"","SYNTHETIC_STALE_ACCEPTANCE"));try(var c=pool.getConnection();var s=c.prepareStatement("INSERT INTO public.mop_asset_export_job(id,tenant_id,created_by,permission_version,accepted_role,command_bytes,trace_id) VALUES (?::uuid,?::uuid,?::uuid,?,'padmin',?,'synthetic-stale-claim')")){s.setString(1,id);s.setString(2,TENANT);s.setString(3,admin);s.setLong(4,a.permissionVersion()+1);s.setBytes(5,command.canonicalBytes());s.executeUpdate();}assertTrue(exports.claim(id,"denial-check",Duration.ofSeconds(30)).isEmpty());try(var c=pool.getConnection();var s=c.prepareStatement("SELECT state,error_code,fencing_token FROM public.mop_asset_export_job WHERE id=?::uuid")){s.setString(1,id);try(var r=s.executeQuery()){r.next();assertEquals("FAILED",r.getString(1));assertEquals("AUTHORIZATION_CHANGED",r.getString(2));assertEquals(0,r.getInt(3));}}assertEquals(a.permissionVersion(),access().permissionVersion());assertEquals(0,attempts(id));assertTrue(exports.list(a,101,null,null).stream().noneMatch(j->j.id().equals(id)));}
    @Test void preparedExpiredClaimMustReconcileRatherThanUploadAgain()throws Exception{var job=accept();exports.claim(job.id(),"preparer",Duration.ofSeconds(1)).orElseThrow();try(var c=pool.getConnection();var s=c.prepareStatement("UPDATE public.mop_asset_export_job SET file_bytes=decode('01020304','hex'),selection_sha256=?,row_count=1,generated_at=statement_timestamp(),updated_at=statement_timestamp(),version=version+1 WHERE id=?::uuid")){s.setString(1,"a".repeat(64));s.setString(2,job.id());s.executeUpdate();}try(var c=pool.getConnection();var s=c.createStatement()){s.execute("SELECT pg_sleep(1.05)");}var reclaimed=exports.claim(job.id(),"reconciler",Duration.ofSeconds(30)).orElseThrow();assertTrue(reclaimed.storageReconciliationRequired());assertEquals(2,reclaimed.fencingToken());assertEquals(State.RECONCILING_STORAGE,exports.get(access(),job.id()).state());try(var c=pool.getConnection();var s=c.prepareStatement("SELECT encode(file_bytes,'hex'),object_id IS NULL FROM public.mop_asset_export_job WHERE id=?::uuid")){s.setString(1,job.id());try(var r=s.executeQuery()){r.next();assertEquals("01020304",r.getString(1));assertTrue(r.getBoolean(2));}}}
    @Test void nextClaimStaysInDedicatedExportQueueAndDoesNotCreateJobs()throws Exception{accept();long before=count("mop_asset_export_job");Optional<Claim> pending=Optional.empty();for(long attempt=0;attempt<=before && pending.isEmpty();attempt++)pending=exports.claimNext("dedicated-export",Duration.ofSeconds(30));var claim=pending.orElseThrow();var a=claim.command().acceptedAccess();var current=exports.get(new AssetExportJobRepository.Access(a.actorId().toString(),a.tenantId().toString(),a.permissionVersion(),"claim-next-readback"),claim.jobId());assertEquals(claim.version(),current.version());assertTrue(current.state()==State.RUNNING||current.state()==State.RECONCILING_STORAGE);assertEquals(before,count("mop_asset_export_job"));}
    @Test void claimAuditFailureRollsBackLeaseAndAutomaticallyCapturedAttempt()throws Exception{
        var job=accept();long audit=count("mop_audit");
        javax.sql.DataSource injected=(javax.sql.DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{javax.sql.DataSource.class},(proxy,method,args)->{
            if(method.getName().equals("getConnection")){Connection real=pool.getConnection();return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{
                if(cm.getName().equals("prepareStatement")&&ca[0] instanceof String sql&&sql.startsWith("INSERT INTO public.mop_audit"))throw new SQLException("SYNTHETIC_CLAIM_AUDIT_FAILURE","22012");
                try{return cm.invoke(real,ca);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}
            });}
            try{return method.invoke(pool,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}
        });
        var p=new PostgresPlatformRepository(injected,mapper);var r=new PostgresAssetExportRepository(injected,p);assertEquals(503,assertThrows(DomainException.class,()->r.claim(job.id(),"faulted",Duration.ofSeconds(30))).status);assertEquals(job,exports.get(access(),job.id()));assertEquals(0,attempts(job.id()));assertEquals(audit,count("mop_audit"));
    }

}
